<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:10px;color:#333}.header{border-bottom:2px solid #0d6efd;margin-bottom:16px}.header h1{color:#0d6efd;margin:0}.meta{color:#6c757d;margin:8px 0}table{width:100%;border-collapse:collapse}th{background:#0d6efd;color:#fff;padding:7px;text-align:left}td{padding:6px;border:1px solid #dee2e6}tr:nth-child(even){background:#f8f9fa}.footer{text-align:center;color:#6c757d;margin-top:14px}</style></head><body><div class="header"><h1>Dentaris</h1><strong>Reporte de inventario</strong></div><p class="meta">Generado: {{ now()->format('d/m/Y H:i') }} · Registros: {{ $inventories->count() }}</p><table><thead><tr><th>Código</th><th>Producto</th><th>Categoría</th><th>Ubicación</th><th>Actual</th><th>Reservado</th><th>Disponible</th><th>Valor</th><th>Estado</th></tr></thead><tbody>@foreach($inventories as $inventory)@php($available=(int)$inventory->available_stock)@php($minimum=(int)($inventory->product->minimum_stock ?? 0))<tr><td>{{ $inventory->product->product_code ?? '' }}</td><td>{{ $inventory->product->name ?? '' }}</td><td>{{ $inventory->product->category ?? '' }}</td><td>{{ $inventory->inventoryLocation->name ?? $inventory->location ?? 'Sin asignar' }}</td><td>{{ $inventory->current_stock }}</td><td>{{ $inventory->reserved_stock }}</td><td>{{ $available }}</td><td>${{ number_format($inventory->current_stock * $inventory->average_cost, 2) }}</td><td>{{ $available <= 0 ? 'Agotado' : ($available <= $minimum ? 'Stock bajo' : 'Disponible') }}</td></tr>@endforeach</tbody></table><p class="footer">Reporte generado por Dentaris</p></body></html>
